WITH listings (id, source_id, indeed_id, title, org, org_type, location, employment_type, seniority,
  description, requirements, qualification, min_years, fresh_grad, nature, posted_at, attribution) AS (
  VALUES
    ('social-work-associate-transitional-shelter-allkin-0f3eea66', '0f3eea664d6f2cefbb6b474affc8fcc3', 'aa2svdsjgtrq',
      'Social Work Associate, Transitional Shelter', 'Allkin Singapore', 'social-community', 'Ang Mo Kio', 'Full-time', 'entry',
      'Supports the social workers at Allkin''s Transitional Shelter, which houses homeless individuals and families while they work towards long-term housing. Duties include screening referrals for admission, helping with client assessments and group programmes, following up after discharge, and handling day-to-day shelter operations such as unit checks and resident queries.',
      'Diploma, preferably in social work (other diplomas considered). Comfortable moving between sites, working varied hours and responding to shelter emergencies. Good MS Office and documentation skills.',
      'diploma', NULL::integer, false, ARRAY['social-work'], DATE '2026-11-23', 'allkin'),
    ('social-work-associate-crest-allkin-4803b004', '4803b00478c6a55882d7ec074fb3e68b', 'aafzvlgjbtmf',
      'Social Work Associate (CREST)', 'Allkin Singapore', 'social-community', 'Serangoon', 'Full-time', 'entry',
      'Part of Allkin''s community outreach team supporting people at risk of or living with mental health conditions, including dementia, and their caregivers. The role runs outreach and cognitive stimulation activities, helps with initial assessments and follow-ups, links clients to services and keeps programme data and reports up to date.',
      'Diploma in social work, counselling, psychology or a related healthcare or community care field. 2 to 3 years of relevant experience preferred, but fresh graduates with practicum experience are welcome. Dialects such as Hokkien, Teochew or Cantonese are a plus.',
      'diploma', NULL, true, ARRAY['social-work', 'community-programmes'], DATE '2026-11-23', 'allkin'),
    ('social-work-associate-fsc-allkin-81147ee8', '81147ee847d5a8f03c5d78deba49bd08', 'aal6qd2s9m6l',
      'Social Work Associate (FSC)', 'Allkin Singapore', 'social-community', 'Ang Mo Kio (may be deployed across Allkin''s Family Service Centres)', 'Full-time', 'entry',
      'Supports casework, counselling and group work across Allkin''s Family Service Centres, under the guidance of senior staff. Day-to-day work includes handling enquiries and intakes, helping run community and programme initiatives, and the admin that keeps group work running.',
      'Diploma, preferably in social work (other diplomas considered). Strong English and organisational skills, and some understanding of policies and schemes that affect clients.',
      'diploma', NULL, false, ARRAY['social-work'], DATE '2026-11-23', 'allkin'),
    ('social-work-associate-montfort-care-710531b3', '710531b3cfa5f71d3015a645f6ea8a5a', 'aakxrb4226s7',
      'Social Work Associate', 'Montfort Care', 'social-community', 'Yishun', 'Full-time', 'entry',
      'Works alongside social workers to deliver casework, group work and community programmes. The role helps plan and run outreach events, collects data for reports and evaluations, and coordinates with clients, partners and other agencies.',
      'Diploma in social sciences, preferably social work; other disciplines may be considered. Fresh graduates are welcome. Comfortable with MS Office.',
      'diploma', NULL, true, ARRAY['social-work', 'community-programmes'], DATE '2026-11-20', 'recruiterpal'),
    ('social-worker-senior-service-allkin-0b69214d', '0b69214d77f174826b33374859dd7f68', 'aa4rj9yhhght',
      'Social Worker, Senior Service', 'Allkin Singapore', 'social-community', 'Serangoon', 'Full-time', 'entry',
      'Supports seniors and their caregivers so seniors can age well at home and in their community. The work covers intake and triage, home visits, psychosocial assessments, person-centred case management and coordinating care with healthcare and community partners.',
      'Bachelor''s, postgraduate diploma or master''s in social work. Open to new graduates and early-career social workers. A local mother tongue or dialect is a plus.',
      'bachelors', NULL, true, ARRAY['social-work', 'case-management'], DATE '2026-11-23', 'allkin'),
    ('social-worker-counsellor-fsc-allkin-8e430a5a', '8e430a5a49c940dff76d7b3bce8fb2ff', 'aadym9jdqkgr',
      'Social Worker / Counsellor (FSC)', 'Allkin Singapore', 'social-community', 'Ang Mo Kio (may be deployed across Allkin''s Family Service Centres)', 'Full-time', 'entry',
      'Provides triage, intake, casework and counselling for individuals and families at Allkin''s Family Service Centres. The role also runs group work, builds community resources and partnerships, and coordinates interventions with other stakeholders.',
      'Bachelor''s degree in social work, counselling or a related field. Experience in casework, counselling, risk management or group work is useful, but new entrants are welcome, especially those with social service internships.',
      'bachelors', NULL, true, ARRAY['social-work', 'counselling'], DATE '2026-11-23', 'allkin'),
    ('social-worker-transitional-shelter-allkin-9c9f8c3d', '9c9f8c3d7b1a2fefa03319ff6b72b52e', 'aamblcwykbfz',
      'Social Worker, Transitional Shelter', 'Allkin Singapore', 'social-community', 'Ang Mo Kio', 'Full-time', 'mid',
      'Handles referrals, admissions and casework for individuals and families staying at Allkin''s Transitional Shelter. This includes psychosocial assessments, case plans, case conferences, therapeutic group work, and planning discharge and follow-up with community partners.',
      'Bachelor''s degree or postgraduate diploma in social work. At least 2 years of direct social work practice, ideally with vulnerable individuals or families.',
      'bachelors', 2, false, ARRAY['social-work'], DATE '2026-11-23', 'allkin'),
    ('social-worker-enabled-living-programme-touch-community-services-877438d3', '877438d38f76a46be318f93d2fd36171', 'aaxmk8lksbrb',
      'Social Worker (Enabled Living Programme)', 'TOUCH Community Services', 'social-community', 'Singapore 159053', 'Full-time', 'mid',
      'Part of TOUCH''s Special Needs Group, providing casework and care coordination for persons with disabilities and their caregivers under the Enabled Living Programme. The role covers intake assessments, referrals, long-term care planning, community outreach and reporting to funders.',
      'Degree or graduate diploma in social work. Registered Social Worker. 2 to 5 years of experience with persons with special needs or disabilities preferred. Apply with TOUCH''s application form and resume.',
      'bachelors', NULL, false, ARRAY['social-work', 'special-needs'], DATE '2026-11-25', 'indeed'),
    ('senior-medical-social-worker-regular-work-hours-rn-care-522f7bb8', '522f7bb8fc396739caf2ddaf0bf30927', 'aafzsqpn48ff',
      'Senior / Medical Social Worker (Regular Work Hours)', 'Undisclosed end-of-life care provider (via RN Care)', 'healthcare', 'Not stated', 'Full-time', 'mid',
      'A medical social work role supporting patients at the end of life and their families, posted by a recruitment agency. The work includes socio-economic assessments, ongoing individual and family counselling, and working with community, religious and social service partners on care plans.',
      'Degree or graduate diploma in social work. Registered with the Singapore Association of Social Workers. Able to work independently across different settings.',
      'bachelors', NULL, false, ARRAY['social-work'], DATE '2026-11-24', 'rn-care'),
    ('medical-social-worker-envirodynamics-solutions-dee1d685', 'dee1d685e04e15088ca0663047d6552a', 'aar8zp4kmf6b',
      'Medical Social Worker', 'Undisclosed academic health system (via EnviroDynamics Solutions)', 'healthcare', 'Jurong East', 'Full-time', 'senior',
      'A medical social work role with a Singapore academic health system, posted by a recruitment agency. The role covers biopsychosocial assessment and intervention for patients, specialised direct care, supervising other medical social workers and staff, and leading projects.',
      'Bachelor''s or graduate diploma in social work. Registered Social Worker with SWAAB. At least 1 year in community health is an advantage.',
      'bachelors', NULL, false, ARRAY['social-work'], DATE '2026-11-26', 'envirodynamics'),
    ('social-worker-counsellor-fam-allkin-singapore-allkin-e1b60613', 'e1b60613fbc901d3c7a574b58e983a26', 'aa9v7tdwbr4s',
      'Social Worker / Counsellor, FAM', 'Allkin Singapore', 'social-community', 'Ang Mo Kio', 'Full-time', 'mid',
      'Works with high-conflict and divorcing families, providing counselling for individuals, couples, parents and children. The role also facilitates supervised visitations, runs therapeutic and psychoeducational groups, and prepares reports for the Family Justice Courts on court-mandated cases.',
      'Counsellors: master''s in counselling recognised by SAC, with SAC clinical membership an advantage. Social workers: bachelor''s in social work or higher, with SWAAB registration an advantage. At least 3 years of therapeutic and group work experience with families and couples. Saturday and some weekday evening work required.',
      'bachelors', 3, false, ARRAY['counselling', 'social-work'], DATE '2026-11-23', 'allkin'),
    ('senior-school-social-and-emotional-guidance-counsellor-north-london-collegiate-school-044f0410', '044f0410643838852cdede9c9b59d4db', 'aagjjc7q6hkz',
      'Senior School Social and Emotional Guidance Counsellor', 'North London Collegiate School (Singapore)', 'education', 'Bukit Merah', 'Contract', 'mid',
      'A school counselling role supporting students in the Senior School section, starting August 2027. The counsellor provides counselling, early intervention and preventive wellbeing support, working with pastoral leads, the safeguarding team, teachers, families and outside specialists.',
      'The listing asks for an experienced counsellor; specific qualifications are not stated in the listing. Subject to background and police checks.',
      'unspecified', NULL, false, ARRAY['counselling'], DATE '2026-11-23', 'indeed'),
    ('psychologist-psychological-service-allkin-f7552216', 'f7552216502a2bb5bdb02c29ea1ef0fa', 'aay4zwt74k29',
      'Psychologist (Psychological Service)', 'Allkin Singapore', 'social-community', 'Serangoon', 'Full-time', 'entry',
      'A clinical or counselling psychologist role in Allkin''s Psychological Service, seeing children, youths and adults with behavioural, socio-emotional and mental health difficulties. The work covers assessments, individual therapy, parent and caregiver support, case consultations, research and training other professionals.',
      'Master''s in clinical or counselling psychology. Registered or eligible for registration with the Singapore Psychological Society. Entry-level; 1 to 2 years of experience preferred. English plus a second language.',
      'masters', NULL, false, ARRAY['clinical-psychology', 'psychology'], DATE '2026-11-23', 'allkin'),
    ('psychologist-individual-couple-therapy-alliance-1d82c029', '1d82c029b8c94dd625b6e40de5cf5259', 'aazhlntsk2hx',
      'Psychologist for individual and couple therapy', 'Alliance Counselling', 'healthcare', 'Bukit Timah', 'Full-time', 'senior',
      'A senior clinical role at a private multidisciplinary practice, providing individual therapy for adults and couples therapy. Focus areas include trauma, attachment, relationships and adult mental health, with chances to build specialist programmes and mentor other clinicians. Some evening and Saturday sessions are expected.',
      'PhD/doctorate or master''s in clinical psychology or a related mental health field. At least 15 years of post-qualification clinical experience. Registered or eligible with a recognised psychology body. Training in a couples therapy approach (e.g. EFT or Gottman) plus experience with EMDR, schema therapy and CBT.',
      'masters', 15, false, ARRAY['clinical-psychology', 'psychology'], DATE '2026-11-23', 'indeed')
)
INSERT INTO jobs (id, source, source_id, source_name, title, org, org_type, location, employment_type,
  seniority, summary, description, requirements, qualification, min_years, fresh_grad, nature,
  posted_at, closes_at, closing_date_estimated, apply_url, source_url, curated)
SELECT id, 'mycareersfuture', source_id,
  CASE attribution
    WHEN 'allkin' THEN 'Indeed (posted via RecruiterPal; recruitment partner Liberte HR)'
    WHEN 'recruiterpal' THEN 'Indeed (posted via RecruiterPal)'
    WHEN 'rn-care' THEN 'Indeed (recruitment agency RN Care, EA 17C8900)'
    WHEN 'envirodynamics' THEN 'Indeed (recruitment agency EnviroDynamics Solutions, EA 12C6285)'
    ELSE 'Indeed'
  END,
  title, org, org_type, location, employment_type, seniority, split_part(description, '. ', 1) || '.',
  description, requirements, qualification, min_years, fresh_grad, nature, posted_at, posted_at + 30, true,
  'https://to.indeed.com/' || indeed_id, 'https://to.indeed.com/' || indeed_id, true
FROM listings
ON CONFLICT (source, source_id) DO UPDATE SET
  source_name = EXCLUDED.source_name,
  title = EXCLUDED.title,
  org = EXCLUDED.org,
  org_uen = EXCLUDED.org_uen,
  org_type = EXCLUDED.org_type,
  location = EXCLUDED.location,
  employment_type = EXCLUDED.employment_type,
  seniority = EXCLUDED.seniority,
  salary_min = EXCLUDED.salary_min,
  salary_max = EXCLUDED.salary_max,
  salary_type = EXCLUDED.salary_type,
  summary = EXCLUDED.summary,
  description = EXCLUDED.description,
  requirements = EXCLUDED.requirements,
  qualification = EXCLUDED.qualification,
  min_years = EXCLUDED.min_years,
  fresh_grad = EXCLUDED.fresh_grad,
  nature = EXCLUDED.nature,
  skills = EXCLUDED.skills,
  posted_at = EXCLUDED.posted_at,
  closes_at = EXCLUDED.closes_at,
  closing_date_estimated = EXCLUDED.closing_date_estimated,
  apply_url = EXCLUDED.apply_url,
  source_url = EXCLUDED.source_url,
  application_action = EXCLUDED.application_action,
  status = EXCLUDED.status,
  curated = EXCLUDED.curated,
  link_checked_at = EXCLUDED.link_checked_at,
  link_missing_count = EXCLUDED.link_missing_count,
  link_missing_code = EXCLUDED.link_missing_code,
  updated_at = EXCLUDED.updated_at;
